   gkyl_gk_collisionless_flux_surf(gkcls->surf_flux_op, 
     &app->local, &species->local, &app->local_ext, &species->local_ext, 
     species->gyro_phi, fin, gkcls->yfield, gkcls->flux_surf, species->cflrate);
+  struct gkyl_msgpack_data *mt = test_bc_twistshift_array_meta_new( (struct test_bc_twistshift_output_meta) {
+      .poly_order = species->basis.poly_order,
+      .basis_type = species->basis.id
+    }
+  );
+  gkyl_grid_sub_array_write(&species->grid, &species->local, mt, gkcls->yfield, "yfield.gkyl");
+  test_bc_twistshift_array_meta_release(mt);
+  assert(false);
 }

