 #include <assert.h>
+#include <stdio.h>
 #include <gkyl_gyrokinetic_priv.h>

+static void
+first_rhs_summary(const char *name, const struct gkyl_array *arr,
+  const struct gkyl_range *local, const struct gkyl_range *local_ext)
+{
+  double sum = 0.0, sumsq = 0.0, maxabs = 0.0;
+  long n = 0;
+  struct gkyl_range_iter iter;
+  gkyl_range_iter_init(&iter, local);
+  while (gkyl_range_iter_next(&iter)) {
+    const double *data = gkyl_array_cfetch(arr, gkyl_range_idx(local_ext, iter.idx));
+    for (size_t c = 0; c < arr->ncomp; ++c) {
+      double v = data[c];
+      sum += v;
+      sumsq += v*v;
+      maxabs = GKYL_MAX2(maxabs, fabs(v));
+      n += 1;
+    }
+  }
+  fprintf(stderr, "FIRST_RHS %s n=%ld sum=% .17e sumsq=% .17e maxabs=% .17e\\n",
+    name, n, sum, sumsq, maxabs);
+}
+
 static void
 gk_species_collisionless_flux_disabled(gkyl_gyrokinetic_app *app, struct gk_species *species,
   struct gk_collisionless *gkcls, const struct gkyl_array *fin)
@@ -21,6 +44,15 @@ gk_species_collisionless_flux_enabled(gkyl_gyrokinetic_app *app, struct gk_speci
   gkyl_gk_collisionless_flux_surf(gkcls->surf_flux_op, 
     &app->local, &species->local, &app->local_ext, &species->local_ext, 
     species->gyro_phi, fin, gkcls->yfield, gkcls->flux_surf, species->cflrate);
+
+  static bool printed = false;
+  if (!printed) {
+    printed = true;
+    first_rhs_summary("gyro_phi", species->gyro_phi, &app->local, &app->local_ext);
+    first_rhs_summary("yfield", gkcls->yfield, &species->local, &species->local_ext);
+    first_rhs_summary("flux_surf", gkcls->flux_surf, &species->local, &species->local_ext);
+    first_rhs_summary("cflrate", species->cflrate, &species->local, &species->local_ext);
+  }
 }

