+        double v = data[c];
+        sumsq += v*v;
+        maxabs = GKYL_MAX2(maxabs, fabs(v));
+      }
+    }
+    fprintf(stderr, "FIRST_RHS_X %s ix=%d sumsq=% .17e maxabs=% .17e\\n",
+      name, ix, sumsq, maxabs);
+  }
